// offline-bundle-scaffold.test.js — THE acceptance test for the P0 G-01
// BUNDLE fix (2026-07-21).
//
// THE BUG: the default (zero-flag) `npm create tess` flow depended on a
// runtime `git clone --depth 1 --branch <DEFAULT_TEMPLATE_REF>` against a
// `create-tess-v*` tag that was never actually cut (see src/scaffold.js's
// header comment for the full incident writeup) — so it failed for every
// user who did not override `--template-ref` explicitly. This is the
// primary onboarding path; the bug was 100% reproducing.
//
// THE FIX: ship the template FILES inside the published npm package
// (create-tess/template/, generated by scripts/build-template.mjs) and
// scaffold the default flow from that bundled LOCAL copy — never a git
// clone, never a network call.
//
// THIS TEST proves the fix end-to-end, from the artifact that actually ships
// to npm — not just from the source tree:
//   1. `npm pack` the REAL package (exercises the `prepack` hook that
//      regenerates template/, and the `files` allowlist that ships it —
//      the same mechanism a real `npm publish` uses).
//   2. Extract the tarball into a throwaway dir — this is now standing in
//      for a real `node_modules/create-tess/` install.
//   3. Run the packed `bin/create-tess.mjs` with ZERO template-source flags
//      (the exact `npm create tess` invocation an end user makes) and with
//      `git` REPLACED by a stub that fails loudly + records the exact argv
//      of every invocation — proving the scaffold succeeds with genuinely
//      no `git clone` dependency, not merely "we didn't pass
//      --template-source this time".
//   4. Assert the produced instance is real and complete: roster installed,
//      CLAUDE.md rendered, `tessctl doctor`/`verify` both pass — and that
//      `git clone` specifically was never invoked (the actual historical
//      bug). NOTE: this deliberately does NOT assert git is invoked ZERO
//      times overall — `keystone.js`'s isInsideGitWorkTree() runs a
//      best-effort, local-only, network-free `git rev-parse --is-inside-
//      work-tree` presence-check even with --no-git-init (see that
//      function's own header comment), purely to report whether the
//      target already sits inside a repo; that is pre-existing, unrelated
//      framework behavior this fix does not touch, fails open (defaults to
//      `false`) when git is unavailable, and never touches the network.
//
// Run: npm test   (or `node --test`)
import { test, after } from 'node:test';
import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
import {
  mkdtempSync,
  rmSync,
  mkdirSync,
  writeFileSync,
  chmodSync,
  readFileSync,
  readdirSync,
  existsSync,
  cpSync,
} from 'node:fs';
import { join, resolve, dirname, delimiter } from 'node:path';
import { tmpdir } from 'node:os';
import { fileURLToPath } from 'node:url';

const TEST_DIR = dirname(fileURLToPath(import.meta.url));
const PKG_DIR = resolve(TEST_DIR, '..'); // create-tess/
const REPO_ROOT = resolve(PKG_DIR, '..'); // tess-os/

const tempDirs = [];
after(() => {
  for (const d of tempDirs) rmSync(d, { recursive: true, force: true });
});

function mkTemp(prefix) {
  const d = mkdtempSync(join(tmpdir(), prefix));
  tempDirs.push(d);
  return d;
}

// `npm pack` runs the `prepack` lifecycle hook (build-template.mjs), which
// destructively rm -rf's + regenerates create-tess/template/ in place. Doing
// that against the SHARED, committed create-tess/template/ while `node --test`
// runs other test FILES concurrently (its default concurrency model) races
// against every other test reading that same directory — copying a repo
// SNAPSHOT first and packing from there means this test's `npm pack` only
// ever mutates its own isolated template/ copy, never the live working tree
// other tests (and the developer's own working copy) rely on.
//
// Uses fs.cpSync directly (recursive: true), never a shelled-out `cp -R
// <src>/. <dest>` — Node's `path.join(REPO_ROOT, '.')` NORMALIZES the
// trailing `.` segment away (join('/a/b', '.') === '/a/b', not '/a/b/.'),
// silently turning the "copy CONTENTS of src into dest" idiom into "copy src
// ITSELF into dest" (landing at `<dest>/tess-os/...` instead of
// `<dest>/...`) — cpSync's own (src, dest) contract has no such ambiguity.
function snapshotRepo() {
  const snap = mkTemp('create-tess-repo-snapshot-');
  cpSync(REPO_ROOT, snap, { recursive: true, dereference: false });
  return join(snap, 'create-tess');
}

// A `git` shim that FAILS LOUDLY and records every invocation to a marker
// file — placed first on PATH so it shadows any real `git` a moment before
// python3/node are resolved from their normal locations. Proves not just
// "the run succeeded" but "git was never even attempted".
function makeFakeBin() {
  const dir = mkTemp('create-tess-fakebin-');
  const marker = join(dir, 'git-was-invoked.marker');
  const gitShim = join(dir, 'git');
  writeFileSync(
    gitShim,
    `#!/bin/sh\necho "$@" >> "${marker}"\necho "fake git: not available (offline test)" >&2\nexit 127\n`,
  );
  chmodSync(gitShim, 0o755);
  return { dir, marker };
}

test(
  'P0 G-01 BUNDLE fix: packed npm tarball scaffolds the DEFAULT flow fully offline, zero git',
  { timeout: 180000 },
  () => {
    // ── 1. Pack the real package, from an isolated repo snapshot (fires
    // `prepack` → build-template.mjs against that snapshot's own template/,
    // never the shared working-tree copy — see snapshotRepo()'s header) ──
    const snapshotCreateTessDir = snapshotRepo();
    const packDest = mkTemp('create-tess-packdest-');
    const packResult = spawnSync(
      'npm',
      ['pack', '--json', '--pack-destination', packDest],
      { cwd: snapshotCreateTessDir, encoding: 'utf8' },
    );
    assert.equal(
      packResult.status,
      0,
      `npm pack failed\nSTDOUT:\n${packResult.stdout}\nSTDERR:\n${packResult.stderr}`,
    );
    // `npm pack --json`'s stdout should be pure JSON (build-template.mjs's
    // prepack summary is intentionally on stderr — see that script). Slicing
    // from the first '[' is a defensive belt-and-suspenders against any
    // OTHER stray banner line npm itself might ever add to stdout.
    const jsonStart = packResult.stdout.indexOf('[');
    assert.ok(
      jsonStart !== -1,
      `npm pack --json produced no JSON array on stdout\nSTDOUT:\n${packResult.stdout}`,
    );
    const packInfo = JSON.parse(packResult.stdout.slice(jsonStart))[0];
    const tarballPath = join(packDest, packInfo.filename);
    assert.ok(existsSync(tarballPath), `expected tarball at ${tarballPath}`);

    // Sanity: the packed tarball's file list (from npm's own manifest,
    // authoritative — not a re-derived guess) must include the bundled
    // template and must NOT include any secret-shaped path.
    const packedFiles = packInfo.files.map((f) => f.path);
    assert.ok(
      packedFiles.some((p) => p.startsWith('template/')),
      'packed tarball must include template/ (the bundled scaffold)',
    );
    assert.ok(
      packedFiles.some((p) => p === 'template/.tess/core/roster-paths.json'),
      'packed tarball must include the roster manifest the wizard reads at scaffold time',
    );
    const secretShaped = packedFiles.filter((p) =>
      /(^|\/)\.env($|\.(?!example))|\.(pem|key|age)$|vault\.age|vault\.recipients|identity\.age|(^|\/)(tess-secrets|secrets|channels)\//.test(
        p,
      ),
    );
    assert.deepEqual(
      secretShaped,
      [],
      `packed tarball must contain no secret-shaped paths; found: ${secretShaped.join(', ')}`,
    );
    assert.ok(
      !packedFiles.some((p) => p.startsWith('template/.tess/keys/verifiers/') || p.startsWith('template/.tess/keys/signoffs/')),
      'packed tarball must not carry this repo\'s own verifier/sign-off trust-anchor keys',
    );

    // MEDIUM-2 (Cyra, PR #160 revision-2): a leftover `.npmignore` bundled
    // into `template/` (a verbatim copy of this repo's own root
    // `.npmignore`, swept in by build-template.mjs before this fix) was
    // silently SHADOWING the `.gitignore`-based structure-preservation
    // pattern at npm's OWN pack step — dropping `kb/raw`, `kb/lint`,
    // `kb/wiki/{concepts,missions,people,synthesis}`, `.tess/snapshots`,
    // `.tess/staging` ENTIRELY from the REAL tarball, invisible to every
    // prior test (which only ever inspected the pre-pack SOURCE tree, never
    // npm's own authoritative `files` manifest for the packed artifact).
    // Asserting against `packedFiles` (npm's own manifest), not the source
    // tree, is the only way to catch this class of gap.
    assert.ok(
      !packedFiles.some((p) => p.endsWith('.npmignore')),
      'packed tarball must not carry any .npmignore (it shadows the .gitignore ' +
        'structure-preservation pattern at npm-pack time and serves no purpose ' +
        'in a scaffolded end-user instance)',
    );
    for (const structurePath of [
      'template/kb/raw/.gitkeep',
      'template/kb/lint/.gitkeep',
      'template/kb/wiki/concepts/.gitkeep',
      'template/kb/wiki/missions/.gitkeep',
      'template/kb/wiki/people/.gitkeep',
      'template/kb/wiki/synthesis/.gitkeep',
      'template/.tess/snapshots/.gitkeep',
      'template/.tess/staging/.gitkeep',
    ]) {
      assert.ok(
        packedFiles.some((p) => p === structurePath),
        `packed tarball must preserve the empty structure at ${structurePath} ` +
          '(regression guard: MEDIUM-2, .npmignore npm-pack-time shadow)',
      );
    }

    // ── 2. Extract into a throwaway dir — standing in for node_modules/create-tess/ ──
    const installDir = mkTemp('create-tess-install-');
    const untar = spawnSync('tar', ['-xzf', tarballPath, '-C', installDir], { encoding: 'utf8' });
    assert.equal(untar.status, 0, `tar extraction failed\nSTDERR:\n${untar.stderr}`);
    const extractedPkgDir = join(installDir, 'package');
    const entry = join(extractedPkgDir, 'bin', 'create-tess.mjs');
    assert.ok(existsSync(entry), `extracted tarball must contain bin/create-tess.mjs at ${entry}`);
    assert.ok(
      existsSync(join(extractedPkgDir, 'template', '.tess', 'core', 'roster-paths.json')),
      'extracted tarball must contain the bundled template on disk',
    );

    // MEDIUM-1 (Cyra, PR #160 revision-2): `operator/user-profile.md` and
    // `conductor/user-profile.md` previously shipped the maintainer's own
    // real, unmodified, byte-for-byte-identical (to the live production
    // Tess instance) behavioral/psychographic calibration profile as the
    // DEFAULT persona for every scaffolded instance. Asserted against the
    // REAL packed-and-extracted tarball content — not the pre-pack source
    // tree — for the same reason as the structure-preservation checks above:
    // this is the artifact that actually ships to npm.
    const bundledUserProfiles = {
      'operator/user-profile.md': readFileSync(
        join(extractedPkgDir, 'template', 'operator', 'user-profile.md'),
        'utf8',
      ),
      'conductor/user-profile.md': readFileSync(
        join(extractedPkgDir, 'template', 'conductor', 'user-profile.md'),
        'utf8',
      ),
    };
    for (const [rel, content] of Object.entries(bundledUserProfiles)) {
      assert.doesNotMatch(
        content,
        /does not think small/i,
        `${rel} must not carry the maintainer's own personal calibration profile (found distinctive phrase)`,
      );
      assert.doesNotMatch(
        content,
        /founder-operator who thinks in systems/i,
        `${rel} must not carry the maintainer's own personal calibration profile (found distinctive phrase)`,
      );
      assert.doesNotMatch(
        content,
        /\bHe\b|\bHis\b/,
        `${rel} must not carry gendered pronouns referring to a specific real individual`,
      );
      assert.match(
        content,
        /<[^>]*>/,
        `${rel} must read as a generic fill-in-the-blank template (expected a placeholder token)`,
      );
    }

    // A real `npm install create-tess` additionally resolves `dependencies`
    // (@clack/prompts, picocolors) into node_modules/ — npm's own dependency
    // install, a well-established mechanism entirely orthogonal to the git-
    // clone bug this test exists to prove fixed. `npm pack`'s tarball
    // deliberately does NOT bundle node_modules (same as every npm package),
    // so reproduce that end state here from the already-resolved snapshot
    // node_modules rather than hitting the registry — this test's "offline"
    // claim is about the SCAFFOLD's own network use (git clone), not about
    // re-proving npm's unrelated, non-broken dependency-install mechanism.
    cpSync(join(snapshotCreateTessDir, 'node_modules'), join(extractedPkgDir, 'node_modules'), {
      recursive: true,
      dereference: false,
    });

    // ── 3. Run the DEFAULT flow — zero --template-source — with git stubbed out ──
    const { dir: fakeBinDir, marker } = makeFakeBin();
    const target = mkTemp('create-tess-offline-target-');
    const env = {
      ...process.env,
      PATH: `${fakeBinDir}${delimiter}${process.env.PATH}`,
      // Belt-and-suspenders against any accidental network dependency: point
      // any http(s) client at an address that cannot resolve/connect.
      HTTP_PROXY: 'http://127.0.0.1:1',
      HTTPS_PROXY: 'http://127.0.0.1:1',
      http_proxy: 'http://127.0.0.1:1',
      https_proxy: 'http://127.0.0.1:1',
    };
    const run = spawnSync(
      process.execPath,
      [
        entry,
        '--yes',
        '--operator=Nomi',
        '--vibe=studio',
        '--path=founders',
        '--pathway=guide',
        '--conductor=Halcyon',
        `--target=${target}`,
        '--no-git-init',
        '--no-gate-hooks',
        // Deliberately NO --template-source / TESS_TEMPLATE_SOURCE — this is
        // the exact zero-flag `npm create tess` default path.
      ],
      { cwd: extractedPkgDir, env, encoding: 'utf8' },
    );
    assert.equal(
      run.status,
      0,
      `offline default-flow scaffold failed\nSTDOUT:\n${run.stdout}\nSTDERR:\n${run.stderr}`,
    );

    // Proves the fetch genuinely used the bundled copy, not a fallback path.
    assert.match(
      run.stdout,
      /bundled template — no network required/,
      'the wizard must report it fetched from the bundled template, not git',
    );

    // ── 4. `git clone` specifically was NEVER invoked — the actual bug ──
    // (see this file's header comment: a benign, local-only, network-free
    // `git rev-parse --is-inside-work-tree` presence-check from
    // keystone.js's isInsideGitWorkTree() is expected and fine here, even
    // with --no-git-init; only `clone` is the historical failure mode).
    const gitInvocations = existsSync(marker) ? readFileSync(marker, 'utf8').trim().split('\n') : [];
    const cloneInvocations = gitInvocations.filter((line) => line.split(/\s+/).includes('clone'));
    assert.deepEqual(
      cloneInvocations,
      [],
      `git clone must never be invoked by the default flow; git was called with: ${gitInvocations.join(' | ') || '(never)'}`,
    );

    // ── The produced instance is real, not a stub ──
    const agentsDir = join(target, '.claude', 'agents');
    assert.ok(existsSync(agentsDir), '.claude/agents/ must exist in the produced instance');
    const installed = readdirSync(agentsDir).filter((f) => f.endsWith('.md'));
    assert.ok(installed.length > 0, 'at least one agent must be installed');

    const claudeMd = readFileSync(join(target, 'CLAUDE.md'), 'utf8');
    assert.match(claudeMd, /Nomi/, 'CLAUDE.md must address the operator by name');
    assert.match(claudeMd, /^#\s+Halcyon — AI Overseer & Conductor/m, 'CLAUDE.md must carry the conductor name');

    assert.ok(
      !existsSync(join(target, 'create-tess')),
      'create-tess/ must never leak into the scaffolded instance',
    );

    const tessctl = (...sub) =>
      spawnSync('python3', [join(target, '.tess', 'bin', 'tessctl'), ...sub], {
        cwd: target,
        env: { ...process.env, TESS_ROOT: target },
        encoding: 'utf8',
      });
    const doctor = tessctl('doctor');
    assert.equal(doctor.status, 0, `tessctl doctor must pass\nSTDOUT:\n${doctor.stdout}\nSTDERR:\n${doctor.stderr}`);
    const verify = tessctl('verify');
    assert.equal(verify.status, 0, `tessctl verify must pass\nSTDOUT:\n${verify.stdout}\nSTDERR:\n${verify.stderr}`);
  },
);

test('a corrupted install (bundle missing) fails with a specific, actionable error — never a silent fallback', () => {
  // Copy bin/+src/+node_modules/+package.json (never template/) into a
  // scratch "install", proving the missing-bundle guard in index.js main()
  // fires with a clear message rather than falling through to
  // isSafeTemplateSource's generic refusal or, worse, silently attempting
  // something else. node_modules is included so the ONLY difference from a
  // real install is the missing template/ — otherwise this would fail on an
  // unrelated MODULE_NOT_FOUND for @clack/prompts before ever reaching the
  // guard being tested. package.json is included so Node's ESM loader knows
  // this tree is `"type": "module"` — without it, the bare `src/*.js` files
  // fall back to being interpreted as CommonJS, and `export`/`import` syntax
  // fails with an unrelated SyntaxError before the guard under test runs.
  const scratch = mkTemp('create-tess-corrupted-install-');
  for (const dir of ['bin', 'src', 'node_modules']) {
    const cp = spawnSync('cp', ['-R', join(PKG_DIR, dir), join(scratch, dir)], { encoding: 'utf8' });
    assert.equal(cp.status, 0, `failed to stage ${dir}/ for the corrupted-install fixture\nSTDERR:\n${cp.stderr}`);
  }
  cpSync(join(PKG_DIR, 'package.json'), join(scratch, 'package.json'));
  const entry = join(scratch, 'bin', 'create-tess.mjs');
  assert.ok(existsSync(entry) && !existsSync(join(scratch, 'template')));

  const target = mkTemp('create-tess-corrupted-target-');
  const run = spawnSync(
    process.execPath,
    [
      entry,
      '--yes',
      '--operator=X',
      '--vibe=rpg',
      '--path=founders',
      '--pathway=chief-of-staff',
      `--target=${target}`,
      '--no-git-init',
      '--no-gate-hooks',
    ],
    { cwd: scratch, encoding: 'utf8' },
  );
  assert.notEqual(run.status, 0, 'a missing bundle must fail, never silently succeed');
  assert.match(
    run.stderr,
    /bundled Tess OS template is missing from this create-tess install/,
    `expected the specific missing-bundle error; got:\nSTDOUT:\n${run.stdout}\nSTDERR:\n${run.stderr}`,
  );
  assert.match(run.stderr, /--template-source/, 'the error must point to the explicit git opt-in workaround');
});

test('the bundled template ships inside the source tree (pre-pack) with the expected structure', () => {
  const bundled = join(PKG_DIR, 'template');
  assert.ok(existsSync(bundled), 'create-tess/template/ must exist (run `npm run build-template`)');
  assert.ok(
    existsSync(join(bundled, '.tess', 'core', 'roster-paths.json')),
    'bundle must contain .tess/core/roster-paths.json',
  );
  assert.ok(!existsSync(join(bundled, 'create-tess')), 'bundle must never contain a nested create-tess/');
  assert.ok(!existsSync(join(bundled, '.git')), 'bundle must never contain a .git directory');
  for (const forbidden of [
    join(bundled, '.tess', 'keys', 'verifiers'),
    join(bundled, '.tess', 'keys', 'signoffs'),
    join(bundled, '.github', 'workflows', 'ci.yml'),
    join(bundled, '.github', 'workflows', 'release.yml'),
    join(bundled, '.github', 'workflows', 'publish-npm.yml'),
  ]) {
    assert.ok(!existsSync(forbidden), `bundle must not contain ${forbidden}`);
  }
});
